import { randomUUID } from "node:crypto";
import { expect, type Page, test } from "@playwright/test";
import { enrollConsoleOwner } from "./owner-fixture.js";

test.beforeEach(async ({ page, baseURL }, testInfo) => {
  await enrollConsoleOwner(page, baseURL, testInfo.project.metadata);
});

async function projectAndInfrastructure(page: Page) {
  const name = `Infrastructure e2e ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  await page
    .getByRole("navigation", { name: "Navigation principale" })
    .getByRole("link", { name: "Infrastructure", exact: true })
    .click();
  await expect(page.getByRole("heading", { name: "Infrastructure", exact: true })).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Exécution non qualifiée", exact: true }),
  ).toBeVisible();
  return name;
}

test("T-AC-19 T-AC-24 prepares a scoped environment from declared inventory and honest local observations", async ({
  page,
}) => {
  const projectName = await projectAndInfrastructure(page);
  const hostName = `Hôte déclaré ${randomUUID().slice(0, 8)}`;
  await expect(
    page.getByText("Aucune mesure collectée. Les capacités du serveur dédié restent inconnues.", {
      exact: true,
    }),
  ).toBeVisible();
  await page.getByLabel("Nom de l’hôte", { exact: true }).fill(hostName);
  await page.getByLabel("Prévoir une VM tâche jetable", { exact: true }).check();

  await page
    .getByRole("button", { name: "Enregistrer l’inventaire souhaité", exact: true })
    .click();

  await expect(page.getByRole("status")).toHaveText(
    "Inventaire souhaité enregistré. Les mesures et la qualification restent indépendantes.",
  );
  await expect(page.getByText(new RegExp(`${hostName} · 3 VM prévues`))).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "PC de développement local", exact: true }),
  ).toHaveCount(0);
  await page.getByRole("button", { name: "Actualiser les mesures", exact: true }).click();
  await expect(
    page.getByRole("heading", { name: "PC de développement local", exact: true }),
  ).toBeVisible();
  await expect(page.getByText("Indisponible", { exact: true })).toBeVisible();
  await expect(page.getByText(/Source : local-system · native-os-fs-v1/)).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Exécution non qualifiée", exact: true }),
  ).toBeVisible();

  const workload = page
    .locator("form")
    .filter({ has: page.getByLabel("Image OCI immuable", { exact: true }) });
  await workload
    .getByRole("combobox", { name: "Projet", exact: true })
    .selectOption({ label: projectName });
  const image = `fixture.invalid/e2e-application@sha256:${"a".repeat(64)}`;
  await workload.getByLabel("Image OCI immuable", { exact: true }).fill(image);
  await workload.getByRole("button", { name: "Préparer l’environnement", exact: true }).click();

  await expect(page.getByRole("status")).toHaveText(
    "Préparation immuable enregistrée. Aucune application n’a démarré.",
  );
  await expect(
    page.getByRole("heading", { name: `Préparé · ${projectName}`, exact: true }),
  ).toBeVisible();
  await expect(page.getByText(image, { exact: true })).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Admettre cette préparation", exact: true }),
  ).toBeDisabled();
  await expect(
    page.getByText(
      "Aucune réservation physique. Les préparations ne provisionnent pas le serveur.",
      { exact: true },
    ),
  ).toBeVisible();
  await page.reload();
  await expect(
    page.getByRole("heading", { name: `Préparé · ${projectName}`, exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "PC de développement local", exact: true }),
  ).toBeVisible();
  await page.screenshot({ path: "artifacts/infrastructure-desktop.png", fullPage: true });
});

test("T-AC-24 keeps public IPv4 exceptions explicit after native owner confirmation and supports mobile", async ({
  page,
}) => {
  await projectAndInfrastructure(page);
  await page.getByRole("button", { name: "Confirmer mon identité", exact: true }).click();
  await expect(page.getByRole("status")).toHaveText("Votre identité a été confirmée.");
  const details = page.locator("details").filter({ has: page.getByText(/^Modifier /) });
  if (await details.count()) await details.locator("summary").click();
  const hostName = `Exception locale ${randomUUID().slice(0, 8)}`;
  await page.getByLabel("Nom de l’hôte", { exact: true }).fill(hostName);
  await page
    .getByRole("combobox", { name: "IPv4 publiques prévues", exact: true })
    .selectOption("2");
  const justification = page.getByLabel("Justification de la seconde IPv4", { exact: true });
  await expect(justification).toHaveAttribute("required", "");
  await expect(justification).toHaveAttribute("minlength", "10");
  await justification.fill("Port fixe de jeu en conflit dans cette déclaration de laboratoire");

  await page
    .getByRole("button", { name: "Enregistrer l’inventaire souhaité", exact: true })
    .click();

  await expect(page.getByRole("status")).toHaveText(
    "Inventaire souhaité enregistré. Les mesures et la qualification restent indépendantes.",
  );
  await expect(page.getByText(/2 IPv4 publique\(s\) souhaitée\(s\)\./)).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Exécution non qualifiée", exact: true }),
  ).toBeVisible();
  await page.reload();
  await expect(page.getByText(new RegExp(`${hostName} ·`))).toBeVisible();
  await page.setViewportSize({ width: 390, height: 844 });
  await expect(page.getByRole("heading", { name: "Infrastructure", exact: true })).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(
    true,
  );
  await page.screenshot({ path: "artifacts/infrastructure-mobile.png", fullPage: true });
});

test("T-AC-24 T05 shows unknown headroom for local observations and pauses then resumes admission", async ({
  page,
}) => {
  await projectAndInfrastructure(page);
  await page.getByRole("button", { name: "Confirmer mon identité", exact: true }).click();
  await expect(page.getByRole("status")).toHaveText("Votre identité a été confirmée.");
  const headroom = page.getByRole("region", { name: "Marge et pression" });
  await expect(headroom.getByText("Pression globale : Inconnu")).toBeVisible();
  await expect(headroom.getByText(/0 en cours sur 1 · 0 en attente sur 4/)).toBeVisible();

  await headroom.getByLabel("Motif de la suspension").fill("Vérification du disque");
  await headroom.getByRole("button", { name: "Suspendre l’admission", exact: true }).click();

  await expect(page.getByRole("status")).toHaveText("Admission suspendue.");
  await expect(headroom.getByRole("heading", { name: "Admission suspendue" })).toBeVisible();
  await expect(headroom.getByText(/Motif : Vérification du disque/)).toBeVisible();
  await expect(page.getByText(/nouvelles admissions sont suspendues/)).toBeVisible();
  await page.reload();
  await expect(headroom.getByRole("heading", { name: "Admission suspendue" })).toBeVisible();

  await page.getByRole("button", { name: "Confirmer mon identité", exact: true }).click();
  await headroom.getByRole("button", { name: "Reprendre l’admission", exact: true }).click();
  await expect(headroom.getByRole("heading", { name: "Admission ouverte" })).toBeVisible();
});
